css:
.brevia1863-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2f36;
    background:
        linear-gradient(180deg, #f4f1ec 0%, #e9e4db 100%);
    border-radius: 16px;
    border: 1px solid #d8d0c4;
}

.brevia1863-container * {
    box-sizing: border-box;
}

.brevia1863-header {
    position: relative;
    text-align: center;
    padding: 28px 22px 24px;
    background:
        repeating-linear-gradient(45deg, rgba(255,255,255,0.03) 0 12px, rgba(0,0,0,0.04) 12px 24px),
        linear-gradient(135deg, #2c3138 0%, #3a4049 55%, #1f242b 100%);
    color: #f2ede4;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #1c2026;
    box-shadow: 0 10px 30px rgba(28, 32, 38, 0.30);
}

.brevia1863-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: #ffffff;
}

.brevia1863-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #f0a830;
    background: rgba(240, 168, 48, 0.12);
    border: 1px solid rgba(240, 168, 48, 0.40);
    padding: 5px 14px;
    border-radius: 4px;
}

.brevia1863-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 0.98rem;
    line-height: 1.55;
    color: #cdd3da;
}

.brevia1863-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.95rem;
    font-weight: 600;
    color: #5d6573;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.brevia1863-period-counter #currentDay,
.brevia1863-period-counter #maxPeriods {
    font-weight: 800;
    color: #b5651d;
}

.brevia1863-round-name {
    background: #3a4049;
    color: #f0a830;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-left: 4px;
}

.brevia1863-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a33a25;
    background: rgba(163, 58, 37, 0.10);
    border: 1px solid rgba(163, 58, 37, 0.35);
    padding: 4px 12px;
    border-radius: 4px;
}

.brevia1863-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.brevia1863-status-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #ddd5c8;
    box-shadow: 0 4px 12px rgba(60, 50, 35, 0.08);
    border-top: 5px solid #9aa1ac;
}

.brevia1863-card-adoption { border-top-color: #2f8f6f; }
.brevia1863-card-engagement { border-top-color: #2d6fb0; }
.brevia1863-card-slippage { border-top-color: #a33a25; }
.brevia1863-card-value { border-top-color: #b5651d; }

.brevia1863-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.7px;
    font-weight: 700;
    color: #7a8290;
}

.brevia1863-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.05;
    margin: 4px 0 2px;
    color: #2b2f36;
    font-variant-numeric: tabular-nums;
}

.brevia1863-card-adoption .brevia1863-value { color: #2f8f6f; }
.brevia1863-card-engagement .brevia1863-value { color: #2d6fb0; }
.brevia1863-card-slippage .brevia1863-value { color: #a33a25; }
.brevia1863-card-value .brevia1863-value { color: #b5651d; }

.brevia1863-sublabel {
    font-size: 0.75rem;
    color: #8a8276;
    line-height: 1.35;
}

/* state highlights */
.brevia1863-engagement-low { border-top-color: #a33a25; }
.brevia1863-engagement-low .brevia1863-value { color: #a33a25; }
.brevia1863-engagement-high { border-top-color: #2f8f6f; }
.brevia1863-engagement-high .brevia1863-value { color: #2f8f6f; }

.brevia1863-slippage-late { border-top-color: #c0392b; }
.brevia1863-slippage-late .brevia1863-value { color: #c0392b; }
.brevia1863-slippage-ontime { border-top-color: #2f8f6f; }
.brevia1863-slippage-ontime .brevia1863-value { color: #2f8f6f; }

.brevia1863-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2c3138;
    border: 1px solid #1c2026;
    color: #e6e1d8;
    padding: 11px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.brevia1863-budget-bar #budgetDisplay {
    font-size: 1.15rem;
    letter-spacing: 0.3px;
    color: #f0a830;
}

.brevia1863-budget-low #budgetDisplay {
    color: #ff7a59;
}

.brevia1863-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 6px solid #b5651d;
    border-radius: 8px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #ddd5c8;
    box-shadow: 0 4px 12px rgba(60, 50, 35, 0.08);
}

.brevia1863-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.brevia1863-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #2b2f36;
    margin-bottom: 6px;
}

.brevia1863-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a5058;
}

.brevia1863-briefing-text strong { color: #b5651d; }
.brevia1863-briefing-text em { color: #a33a25; font-style: italic; }

.brevia1863-controls {
    background: #ffffff;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddd5c8;
    box-shadow: 0 4px 12px rgba(60, 50, 35, 0.08);
}

.brevia1863-controls h3 {
    margin: 0 0 16px;
    font-size: 1.1rem;
    font-weight: 800;
    color: #2b2f36;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    border-bottom: 3px solid #ece6dc;
    padding-bottom: 8px;
}

.brevia1863-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a4049;
    margin: 14px 0 6px;
}

.brevia1863-container select,
.brevia1863-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9c0b0;
    border-radius: 7px;
    font-size: 0.92rem;
    background-color: #faf8f4;
    color: #2b2f36;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.brevia1863-container select:focus,
.brevia1863-container input[type="number"]:focus {
    outline: none;
    border-color: #b5651d;
    box-shadow: 0 0 0 3px rgba(181, 101, 29, 0.18);
}

.brevia1863-container select option {
    background-color: #faf8f4;
    color: #2b2f36;
}

.brevia1863-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b5651d;
}

.brevia1863-range-readout,
.brevia1863-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5d6573;
    margin-top: 4px;
}

.brevia1863-range-readout span:last-child,
.brevia1863-alloc-readout span:nth-child(2) {
    color: #b5651d;
    font-weight: 800;
}

.brevia1863-menu {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.brevia1863-check {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: #faf8f4;
    border: 1px solid #ddd5c8;
    border-radius: 7px;
    padding: 10px 12px;
    font-weight: 600;
    font-size: 0.88rem;
    color: #3a4049;
    margin: 0;
    cursor: pointer;
}

.brevia1863-check input[type="checkbox"] {
    margin-top: 3px;
    accent-color: #2f8f6f;
    flex: 0 0 auto;
    width: 16px;
    height: 16px;
}

.brevia1863-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.brevia1863-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #faf8f4;
    border: 1px solid #e0d8cb;
    border-radius: 7px;
    padding: 8px 12px;
}

.brevia1863-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3a4049;
}

.brevia1863-alloc-row input[type="number"] {
    width: 88px;
    flex: 0 0 88px;
}

.brevia1863-shock {
    background: rgba(163, 58, 37, 0.08);
    border: 1px solid rgba(163, 58, 37, 0.35);
    border-left: 5px solid #a33a25;
    border-radius: 7px;
    padding: 11px 14px;
    margin: 14px 0 4px;
    font-size: 0.88rem;
    font-weight: 600;
    color: #8a2a18;
    line-height: 1.45;
}

.brevia1863-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.brevia1863-container .btn-primary {
    background: linear-gradient(135deg, #b5651d 0%, #f0a830 100%);
    border: none;
    color: #2b1c08;
    padding: 11px 28px;
    border-radius: 7px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    box-shadow: 0 6px 16px rgba(181, 101, 29, 0.35);
}

.brevia1863-container .btn-primary:hover {
    filter: brightness(1.06);
}

.brevia1863-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c9c0b0;
    color: #5d6573;
    background: transparent;
}

.brevia1863-coach {
    background: #2c3138;
    color: #d8d3c8;
    border: 1px solid #1c2026;
    border-left: 5px solid #f0a830;
    border-radius: 10px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(28, 32, 38, 0.20);
}

.brevia1863-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0a830;
    margin-bottom: 8px;
}

.brevia1863-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #e0dbd0;
}

.brevia1863-coach-body strong { color: #f0a830; }
.brevia1863-coach-body em { color: #ff9d6b; font-style: italic; }

.brevia1863-history,
.brevia1863-chart {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddd5c8;
    box-shadow: 0 4px 12px rgba(60, 50, 35, 0.08);
}

.brevia1863-history h3,
.brevia1863-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2b2f36;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.brevia1863-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4049;
}

.brevia1863-container table#usfHistoryTable th {
    background: #2c3138;
    color: #f0a830;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1c2026;
}

.brevia1863-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ece6dc;
    color: #4a5058;
}

.brevia1863-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f4;
}

.brevia1863-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .brevia1863-container {
        padding: 14px;
    }
    .brevia1863-header h1 {
        font-size: 1.6rem;
    }
    .brevia1863-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .brevia1863-value {
        font-size: 2.05rem;
    }
    .brevia1863-clock {
        margin-left: 0;
    }
    .brevia1863-period-counter {
        font-size: 0.86rem;
    }
    .brevia1863-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .brevia1863-alloc-row {
        flex-wrap: wrap;
    }
    .brevia1863-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .brevia1863-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.brevia1863-cm { background:#f7f8fa; color:#141821; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.brevia1863-cm-head { text-align:center; border-bottom:1px solid #dfe3ea; padding-bottom:14px; margin-bottom:16px; }
.brevia1863-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#5c6472; font-weight:700; }
.brevia1863-cm-scorewrap { margin:8px 0 2px; }
.brevia1863-cm-score { font-size:52px; font-weight:800; color:#5a3fd6; line-height:1; }
.brevia1863-cm-score-max { font-size:20px; color:#8891a0; font-weight:600; }
.brevia1863-cm-grade { font-size:19px; font-weight:700; color:#141821; margin-top:4px; }
.brevia1863-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.brevia1863-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.brevia1863-cm-met { background:#e2dcfb; color:#4a30b8; }
.brevia1863-cm-fail { background:#fce0dc; color:#a4322a; }
.brevia1863-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.brevia1863-cm-metric { background:#eef0f5; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.brevia1863-cm-metric-val { font-size:22px; font-weight:800; color:#141821; }
.brevia1863-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#5c6472; margin-top:3px; }
.brevia1863-cm-insights { background:#eef0f5; border-radius:10px; padding:14px 18px; }
.brevia1863-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#5c6472; font-weight:700; margin-bottom:8px; }
.brevia1863-cm-insights ul { margin:0; padding-left:18px; }
.brevia1863-cm-insights li { font-size:14px; line-height:1.5; color:#2c333f; margin-bottom:7px; }

