(function() {
    'use strict';

    class BreviaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Engage to Innovate`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Brevia Strumenti S.p.A. / Brevia Sense).
            this.RUNWAY = 2.3;          // EUR 2.3M remaining runway
            this.BURN = 0.29;           // EUR 290k/month burn
            this.WARROOM = 0.06;        // EUR 60k war-room week
            this.BACKFILL = 0.045;      // EUR 45k backfill two engineers
            this.START_ENGAGE = 41;     // engagement pulse now (peak was 78)
            this.START_SLIP = 5.0;      // 5 weeks late at current velocity
            this.MAX_VALUE = 11.0;      // EUR 11M lead-customer annual sales = full prize

            // Concept truths.
            this.TRUE_ROOT = `engagement`;
            this.TRUE_LEVER = `engagement`;
            this.TRUE_FLEX = `sprint`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    adoption: 0,                 // share of the 9 surfaced ideas shipped (0-100)
                    engagement: this.START_ENGAGE,
                    slippage: this.START_SLIP,   // weeks late vs EMO (lower better)
                    value: 0,                    // EUR M of features that land at EMO
                    runway: this.RUNWAY,         // EUR M remaining
                    spent: 0,                    // EUR M of interventions committed
                    goldPlated: false,
                    schedOnly: false,
                    boughtActivity: false,
                    adoptionHistory: [0],
                    engagementHistory: [this.START_ENGAGE],
                    slippageHistory: [this.START_SLIP],
                    valueHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Deliberately middling / wrong-leaning defaults so a click-through cannot auto-win.
                state.decisions = {
                    root: `schedule`,
                    lever: `resources`,
                    rigor: 50,
                    flex: `locked`,
                    ritual: true,
                    warroom: false,
                    customer: false,
                    backfill: false,
                    autonomy: false,
                    predict: `none`,
                    integration: 40,
                    edge: 20,
                    debt: 20,
                    hardening: 20,
                    pilot: `balanced`,
                    report: `partial`,
                    gono: `conditional`,
                    keep: `ritual`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rt = document.getElementById(`rootInput`);
                const lv = document.getElementById(`leverInput`);
                const rg = document.getElementById(`rigorInput`);
                if (rt) decisions.root = rt.value;
                if (lv) decisions.lever = lv.value;
                if (rg) decisions.rigor = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const fx = document.getElementById(`flexInput`);
                const ri = document.getElementById(`ritualInput`);
                const wr = document.getElementById(`warroomInput`);
                const cu = document.getElementById(`customerInput`);
                const bf = document.getElementById(`backfillInput`);
                const au = document.getElementById(`autonomyInput`);
                const pr = document.getElementById(`predictInput`);
                if (fx) decisions.flex = fx.value;
                if (ri) decisions.ritual = ri.checked;
                if (wr) decisions.warroom = wr.checked;
                if (cu) decisions.customer = cu.checked;
                if (bf) decisions.backfill = bf.checked;
                if (au) decisions.autonomy = au.checked;
                if (pr) decisions.predict = pr.value;
                // Budget guard: the costed interventions must fit the remaining runway.
                const cost = (decisions.warroom ? this.WARROOM : 0) + (decisions.backfill ? this.BACKFILL : 0);
                if (cost > state.domainState.runway + 0.0001) {
                    warn(`warn_budget`); return false;
                }
                if (!decisions.ritual && !decisions.warroom && !decisions.customer && !decisions.backfill && !decisions.autonomy) {
                    warn(`warn_no_intervention`); return false;
                }
            } else if (round === 3) {
                const ig = document.getElementById(`integrationInput`);
                const ed = document.getElementById(`edgeInput`);
                const db = document.getElementById(`debtInput`);
                const hd = document.getElementById(`hardeningInput`);
                const pl = document.getElementById(`pilotInput`);
                if (ig) decisions.integration = parseFloat(ig.value);
                if (ed) decisions.edge = parseFloat(ed.value);
                if (db) decisions.debt = parseFloat(db.value);
                if (hd) decisions.hardening = parseFloat(hd.value);
                if (pl) decisions.pilot = pl.value;
                const parts = [decisions.integration, decisions.edge, decisions.debt, decisions.hardening];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.integration + decisions.edge + decisions.debt + decisions.hardening);
                if (total !== 100) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 4) {
                const rp = document.getElementById(`reportInput`);
                const gn = document.getElementById(`gonoInput`);
                const kp = document.getElementById(`keepInput`);
                const cv = document.getElementById(`convictionInput`);
                if (rp) decisions.report = rp.value;
                if (gn) decisions.gono = gn.value;
                if (kp) decisions.keep = kp.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let adoptionDelta = 0, engageDelta = 0, slipDelta = 0, valueDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSE — separate delivery / human / process; name the unlocking root cause.
                switch (d.root) {
                    case `engagement`:
                        engageDelta += 6; adoptionDelta += 4; slipDelta -= 0.3; coachKey = `coach_r1_engagement`; break;
                    case `scope`:
                        slipDelta -= 0.1; coachKey = `coach_r1_scope`; break;
                    case `schedule`:
                        // Common Error 1: schedule-only thinking ignores the collapsed pulse.
                        ds.schedOnly = true; engageDelta -= 4; slipDelta += 0.2; coachKey = `coach_r1_schedule`; break;
                    case `none`:
                        engageDelta -= 3; coachKey = `coach_r1_none`; break;
                }

                // Which lever is most underused? Engagement is the concept's answer.
                switch (d.lever) {
                    case `engagement`:
                        adoptionDelta += 4; engageDelta += 4; if (d.root === `engagement`) coachKey = `coach_r1_sharp`; break;
                    case `flexibility`:
                        slipDelta -= 0.2; break;
                    case `resources`:
                        engageDelta -= 2; coachKey = (d.root === `schedule`) ? `coach_r1_schedule` : coachKey; break;
                }

                // Diagnostic rigor: separating the three problems before acting.
                if (d.rigor >= 60) { engageDelta += 4; adoptionDelta += 2; }
                else if (d.rigor <= 25) { engageDelta -= 3; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.root === `engagement` && d.lever === `engagement`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // SET FLEXIBILITY + CHOOSE ENGAGEMENT INTERVENTIONS.
                // (a) Flexibility — Common Error 2: freezing everything; also penalize fully-open chaos.
                switch (d.flex) {
                    case `sprint`:
                        // Right amount: credible core frozen, the rest a flexible per-sprint backlog.
                        slipDelta -= 0.6; engageDelta += 5; valueDelta += 1.2; coachKey = `coach_r2_sprint`; break;
                    case `monthly`:
                        slipDelta -= 0.3; engageDelta += 3; valueDelta += 0.6; coachKey = `coach_r2_monthly`; break;
                    case `locked`:
                        // Ship a pilot the customer no longer wants — value cannot absorb edge filtering.
                        valueDelta -= 1.5; engageDelta -= 3; slipDelta += 0.3; coachKey = `coach_r2_locked`; break;
                    case `open`:
                        // No frozen core — thrash, the critical path never stabilizes.
                        slipDelta += 0.8; engageDelta -= 2; coachKey = `coach_r2_open`; break;
                }

                // (b) Engagement interventions (costed menu).
                if (d.ritual) {
                    // Idea-adoption ritual: high-leverage, low-cost; lifts adoption AND engagement.
                    adoptionDelta += 32; engageDelta += 8;
                    // Costs scope/time unless flexibility makes room for it.
                    slipDelta += (d.flex === `locked`) ? 0.5 : 0.1;
                }
                if (d.warroom) { spend += this.WARROOM; engageDelta += 5; slipDelta -= 0.4; }
                if (d.customer) {
                    // Exposes the gap early — uncomfortable now, protects delivered value at EMO.
                    valueDelta += 1.2; slipDelta -= 0.2; if (d.flex === `locked`) valueDelta -= 0.4;
                }
                if (d.backfill) {
                    spend += this.BACKFILL;
                    // Onboarding drag: short-term slip, medium-term capacity.
                    slipDelta += 0.3; engageDelta += 2;
                }
                if (d.autonomy) {
                    // Recognition-and-autonomy: designs the cooperation, heals sub-team friction.
                    engageDelta += 9; adoptionDelta += 6;
                }

                // Deferring every idea again (Common Error 3): no ritual AND no autonomy.
                if (!d.ritual && !d.autonomy) { engageDelta -= 6; adoptionDelta -= 4; coachKey = `coach_r2_noidea`; }

                // Tie the spend to a metric (Common Error 4: buying activity, not outcomes).
                switch (d.predict) {
                    case `engagement`: engageDelta += 4; break;
                    case `adoption`: adoptionDelta += 4; break;
                    case `none`:
                        ds.boughtActivity = true; engageDelta -= 3;
                        if (d.warroom || d.backfill) coachKey = `coach_r2_activity`;
                        break;
                }

                summaryKey = (d.flex === `sprint` && (d.ritual || d.autonomy) && d.predict !== `none`) ? `sum_r2_good` :
                             (d.flex === `locked` ? `sum_r2_frozen` : `sum_r2_weak`);
            } else if (round === 3) {
                // ALLOCATE the sprint + define the minimum-viable pilot, absorbing the poaching shock.
                const ig = d.integration / 100;
                const ed = d.edge / 100;
                const db = d.debt / 100;
                const hd = d.hardening / 100;

                // The poach removes ~15% of effective integration capacity.
                const effIntegration = Math.max(0, ig - 0.15);

                // Critical path (integration) drives slippage down; starving it lets the demo slip.
                slipDelta -= effIntegration * 6 - 1.5;            // need >25% effective integration to break even

                // Delivered value: integration unlocks the base demo; edge filter is the high-value ask.
                valueDelta += effIntegration * 4.5 + ed * 4.0 + hd * 2.0;

                // Technical debt buys no EMO value but reduces future rework / protects engagement a little.
                engageDelta += db * 4;
                if (db <= 0.05) engageDelta -= 1;                 // ignoring debt entirely costs morale slightly

                // Edge filtering only lands as value if flexibility left room for it.
                if (d.flex === `locked` && d.edge > 0) { valueDelta -= ed * 2.5; coachKey = `coach_r3_frozenedge`; }

                // Define the minimum-credible pilot (Common Error 5: gold-plating).
                switch (d.pilot) {
                    case `minimal`:
                        // Smallest credible pilot — protects runway and the deadline.
                        slipDelta -= 0.6; valueDelta += 1.0; coachKey = (coachKey === `coach_default`) ? `coach_r3_minimal` : coachKey; break;
                    case `balanced`:
                        valueDelta += 1.5; coachKey = (coachKey === `coach_default`) ? `coach_r3_balanced` : coachKey; break;
                    case `gold`:
                        // Maximum pilot inflates the burn — runs out of cash before EMO.
                        ds.goldPlated = true; spend += 0.9; slipDelta += 1.0; valueDelta -= 1.0; coachKey = `coach_r3_gold`; break;
                }

                // Starving the critical path to chase the customer feature.
                if (d.integration < 25) { slipDelta += 1.0; coachKey = `coach_r3_starve`; }
                else if (d.integration >= 40 && d.edge >= 20 && d.debt <= 25 && d.pilot !== `gold`) { coachKey = `coach_r3_protected`; }

                summaryKey = (d.integration >= 40 && d.edge >= 15 && d.pilot !== `gold` && d.debt <= 30) ? `sum_r3_good` :
                             (ds.goldPlated ? `sum_r3_gold` : (d.integration < 25 ? `sum_r3_starved` : `sum_r3_weak`));
            } else if (round === 4) {
                // RECOVER, present the scorecard, go/no-go, institutionalize.
                switch (d.report) {
                    case `scorecard`:
                        // All four KPIs vs baseline + justified trade-offs.
                        engageDelta += 5; coachKey = `coach_r4_scorecard`; break;
                    case `partial`:
                        coachKey = `coach_r4_partial`; break;
                    case `spin`:
                        // Spin destroys trust with both sponsor and customer.
                        engageDelta -= 5; valueDelta -= 0.5; coachKey = `coach_r4_spin`; break;
                }

                // Go/no-go must match what was actually delivered.
                const credible = ds.slippage <= 1.0 && ds.value >= 5.0;
                switch (d.gono) {
                    case `go`:
                        if (credible) { valueDelta += 1.0; coachKey = `coach_r4_go`; }
                        else { valueDelta -= 1.0; engageDelta -= 2; coachKey = `coach_r4_overcommit`; }
                        break;
                    case `conditional`:
                        valueDelta += credible ? 0.5 : 0.2; break;
                    case `nogo`:
                        // Honest no-go saves face only if the pilot truly isn't ready.
                        if (credible) { valueDelta -= 1.5; coachKey = `coach_r4_undersell`; }
                        else { engageDelta += 2; coachKey = `coach_r4_honest_nogo`; }
                        break;
                }

                // Institutionalize — keep the operating model, not just the crisis fix.
                switch (d.keep) {
                    case `operating`: engageDelta += 8; adoptionDelta += 6; coachKey = `coach_r4_institutionalize`; break;
                    case `ritual`: engageDelta += 4; adoptionDelta += 3; break;
                    case `nothing`: engageDelta -= 6; adoptionDelta -= 6; coachKey = `coach_r4_revert`; break;
                }

                if (d.conviction >= 60) { engageDelta += 4; }
                else if (d.conviction <= 25) { engageDelta -= 4; }

                summaryKey = (d.report === `scorecard` && d.keep === `operating`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: interventions and gold-plating draw down the runway.
            spend = Math.round(spend * 1000) / 1000;
            ds.spent = Math.round((ds.spent + spend) * 1000) / 1000;
            ds.runway = Math.max(0, Math.round((ds.runway - spend) * 1000) / 1000);

            // If the runway is exhausted, value cannot be finished — a demo you can't afford is worth zero.
            if (ds.runway <= 0.0001) { valueDelta = Math.min(valueDelta, -0.5); engageDelta -= 3; }

            // Apply deltas with clamps. Slippage 0..8 weeks, value 0..MAX, others 0..100.
            ds.adoption = Math.max(0, Math.min(100, Math.round(ds.adoption + adoptionDelta)));
            ds.engagement = Math.max(0, Math.min(100, Math.round(ds.engagement + engageDelta)));
            ds.slippage = Math.max(0, Math.min(8, Math.round((ds.slippage + slipDelta) * 10) / 10));
            ds.value = Math.max(0, Math.min(this.MAX_VALUE, Math.round((ds.value + valueDelta) * 10) / 10));

            ds.adoptionHistory.push(ds.adoption);
            ds.engagementHistory.push(ds.engagement);
            ds.slippageHistory.push(ds.slippage);
            ds.valueHistory.push(ds.value);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                adoption: ds.adoption,
                adoptionDelta: Math.round(adoptionDelta),
                engagement: ds.engagement,
                engageDelta: Math.round(engageDelta),
                slippage: ds.slippage,
                slipDelta: Math.round(slipDelta * 10) / 10,
                value: ds.value,
                valueDelta: Math.round(valueDelta * 10) / 10,
                runway: ds.runway,
                goldPlated: ds.goldPlated,
                schedOnly: ds.schedOnly,
                boughtActivity: ds.boughtActivity,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR: English "€2.3M" (symbol before), Spanish "2,3 M€" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M€`;
            }
            return `${sign}€${abs.toFixed(1)}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`adoptionDisplay`, `domainState.adoption`, (v) => Math.round(Number(v)));
            uiManager.bind(`engagementDisplay`, `domainState.engagement`, (v) => {
                const card = document.querySelector(`.brevia1863-card-engagement`);
                if (card) {
                    card.classList.toggle(`brevia1863-engagement-low`, Number(v) < 50);
                    card.classList.toggle(`brevia1863-engagement-high`, Number(v) >= 70);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`slippageDisplay`, `domainState.slippage`, (v) => {
                const card = document.querySelector(`.brevia1863-card-slippage`);
                if (card) {
                    card.classList.toggle(`brevia1863-slippage-late`, Number(v) >= 2);
                    card.classList.toggle(`brevia1863-slippage-ontime`, Number(v) <= 0.5);
                }
                return Number(v).toFixed(1);
            });
            uiManager.bind(`valueDisplay`, `domainState.value`, (v) => self._fmtMoney(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.runway`, (v) => {
                const bar = document.querySelector(`.brevia1863-budget-bar`);
                if (bar) bar.classList.toggle(`brevia1863-budget-low`, Number(v) <= 0.5);
                return self._fmtMoney(Number(v));
            });

            // Diagnostic rigor slider readout.
            const rg = document.getElementById(`rigorInput`);
            const rgReadout = document.getElementById(`rigorReadout`);
            if (rg && rgReadout) {
                rgReadout.textContent = rg.value;
                rg.addEventListener(`input`, function() { rgReadout.textContent = rg.value; });
            }

            // Sprint-capacity live total (must hit 100%).
            const allocIds = [`integrationInput`, `edgeInput`, `debtInput`, `hardeningInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.brevia1863-alloc-readout`);
                if (bar) bar.style.color = (total !== 100) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        getChartConfig() {
            return {
                breviaChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: window.mySimulation.t(`legend_adoption`),
                                data: [],
                                borderColor: `#2f8f6f`,
                                backgroundColor: `rgba(47,143,111,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f8f6f`,
                                yAxisID: `y`
                            },
                            {
                                label: window.mySimulation.t(`legend_engagement`),
                                data: [],
                                borderColor: `#2d6fb0`,
                                backgroundColor: `rgba(45,111,176,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2d6fb0`,
                                yAxisID: `y`
                            },
                            {
                                label: window.mySimulation.t(`legend_slippage`),
                                data: [],
                                borderColor: `#a33a25`,
                                backgroundColor: `rgba(163,58,37,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#a33a25`,
                                yAxisID: `y1`
                            },
                            {
                                label: window.mySimulation.t(`legend_dvalue`),
                                data: [],
                                borderColor: `#b5651d`,
                                backgroundColor: `rgba(181,101,29,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b5651d`,
                                yAxisID: `y1`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#4a5058`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7a8290` }, grid: { color: `rgba(0,0,0,0.06)` },
                                title: { display: true, text: window.mySimulation.t(`axis_ae`), color: `#7a8290` }
                            },
                            y1: {
                                beginAtZero: true, max: 12, position: `right`,
                                ticks: { color: `#7a8290` }, grid: { drawOnChartArea: false },
                                title: { display: true, text: window.mySimulation.t(`axis_weeks`), color: `#7a8290` }
                            },
                            x: {
                                ticks: { color: `#7a8290` }, grid: { color: `rgba(0,0,0,0.04)` },
                                title: { display: true, text: window.mySimulation.t(`axis_round`), color: `#7a8290` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.engagementHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                breviaChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.adoptionHistory },
                        { data: ds.engagementHistory },
                        { data: ds.slippageHistory },
                        { data: ds.valueHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const adoption = Math.round(ds.adoption);
            const engagement = Math.round(ds.engagement);
            const slippage = ds.slippage;
            const value = ds.value;
            const onTimeScore = Math.max(0, 100 - slippage * 18);
            const valueScore = Math.min(100, (value / this.MAX_VALUE) * 100);
            return Math.round(engagement * 0.30 + adoption * 0.22 + onTimeScore * 0.26 + valueScore * 0.22);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const adoption = Math.round(ds.adoption);
            const engagement = Math.round(ds.engagement);
            const slippage = ds.slippage;
            const value = ds.value;
            const runway = ds.runway;

            // Composite: engagement and adoption are the levers; on-time delivery and value are the prize.
            const composite = this._composite(ds);

            const onTime = slippage <= 1.0;
            const engaged = engagement >= 65;
            const delivered = value >= 6.0;
            const solvent = runway > 0.0001;
            const stalled = (ds.schedOnly && engagement < 55) || (ds.boughtActivity && adoption < 30) || !solvent;

            let performanceKey = `grade_flatline`;
            if (onTime && engaged && delivered && solvent && composite >= 75) performanceKey = `grade_lands`;
            else if (delivered && onTime && solvent) performanceKey = `grade_delivered`;
            else if (engaged && adoption >= 50) performanceKey = `grade_recovered`;
            else if (!solvent || ds.goldPlated) performanceKey = `grade_burned`;
            else if (stalled) performanceKey = `grade_stalled`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const met = onTime && engaged && delivered && solvent && composite >= 75;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (onTime && engaged && delivered && solvent) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (stalled) insights.push(window.mySimulation.t(`insight_stalled`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (slippage > 1.0) insights.push(window.mySimulation.t(`insight_late`));
            else insights.push(window.mySimulation.t(`insight_ontime`));
            if (ds.schedOnly && engagement < 60) insights.push(window.mySimulation.t(`insight_schedonly`));
            if (ds.boughtActivity) insights.push(window.mySimulation.t(`insight_activity`));
            if (ds.goldPlated || !solvent) insights.push(window.mySimulation.t(`insight_goldplate`));
            if (adoption >= 60 && engagement >= 65) insights.push(window.mySimulation.t(`insight_ideas`));

            return {
                adoption: adoption,
                engagement: engagement,
                slippage: slippage,
                value: value,
                runway: runway,
                onTime: onTime,
                engaged: engaged,
                delivered: delivered,
                solvent: solvent,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                stalled: stalled,
                goldPlated: !!ds.goldPlated,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="brevia1863-cm-badge ` + (s.met ? `brevia1863-cm-met` : `brevia1863-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.solvent === false || s.goldPlated) badges.push(`<span class="brevia1863-cm-badge brevia1863-cm-fail">` + t(`cm_fail_burned`) + `</span>`);
            if (s.stalled) badges.push(`<span class="brevia1863-cm-badge brevia1863-cm-fail">` + t(`cm_fail_stalled`) + `</span>`);
            if (s.delivered === false) badges.push(`<span class="brevia1863-cm-badge brevia1863-cm-fail">` + t(`cm_fail_undelivered`) + `</span>`);
            const kpi = (label, val) => `<div class="brevia1863-cm-metric"><div class="brevia1863-cm-metric-val">` + val + `</div><div class="brevia1863-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_engagement`), (s.engagement != null ? s.engagement : 0)) + kpi(t(`cm_adoption`), (s.adoption != null ? s.adoption : 0)) + kpi(t(`cm_slippage`), (s.slippage != null ? s.slippage : 0)) + kpi(t(`cm_value`), (s.value != null ? s.value : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="brevia1863-cm">`
                + `<div class="brevia1863-cm-head"><div class="brevia1863-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="brevia1863-cm-scorewrap"><span class="brevia1863-cm-score">` + score + `</span><span class="brevia1863-cm-score-max">/100</span></div>`
                + `<div class="brevia1863-cm-grade">` + grade + `</div>`
                + `<div class="brevia1863-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="brevia1863-cm-metrics">` + kpis + `</div>`
                + `<div class="brevia1863-cm-insights"><div class="brevia1863-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.runway <= 0.2) return window.mySimulation.t(`hint_runway`);
            if (ds.goldPlated) return window.mySimulation.t(`hint_goldplate`);
            if (ds.schedOnly && ds.engagement < 55) return window.mySimulation.t(`hint_schedonly`);
            if (ds.boughtActivity) return window.mySimulation.t(`hint_activity`);
            if (state.currentPeriod >= 2 && ds.engagement < 50) return window.mySimulation.t(`hint_engagement`);
            if (state.currentPeriod >= 3 && ds.slippage >= 2) return window.mySimulation.t(`hint_slippage`);
            if (ds.engagement >= 65 && ds.adoption >= 50 && ds.slippage <= 1) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.adoption`, label: `Adoption`, i18nKey: `col_adoption`, formatter: (v) => Math.round(v) },
                { key: `results.engagement`, label: `Engagement`, i18nKey: `col_engagement`, formatter: (v) => Math.round(v) },
                { key: `results.slippage`, label: `Slippage`, i18nKey: `col_slippage`, formatter: (v) => Number(v).toFixed(1) },
                { key: `results.value`, label: `Value`, i18nKey: `col_value`, formatter: (v) => self._fmtMoney(Number(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

